function parse(x,f){try{return JSON.parse(x)??f}catch{return f}}
const defaults={read:{},seen:{},marks:{},cards:{},last:null,dark:false,history:[]};let S={...defaults,...parse(read(stateKey),{})};for(const k of ['read','seen','marks','cards'])if(!S[k]||typeof S[k]!=='object')S[k]={};if(!Array.isArray(S.history))S.history=[];
function save(){write(stateKey,JSON.stringify(S))}function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}const fmt=n=>Number(n).toLocaleString('vi-VN');const pct=(a,b)=>b?Math.round(a/b*100):0;
const meta=Object.fromEntries(I.flatMap(m=>m.los.map(l=>[l.id,{...l,module:m}]))), all=Object.values(meta), subjectNames=[['QM','Quantitative Methods','Định lượng','#2656a5','#eaf0fc'],['EC','Economics','Kinh tế học','#98611f','#fcf0df'],['CI','Corporate Issuers','Tài chính doanh nghiệp','#0b776c','#e2f6ef'],['FS','Financial Statement Analysis','Phân tích BCTC','#7b53a5','#f2eafa'],['EQ','Equity Investments','Cổ phiếu','#207a49','#e6f4e9'],['FI','Fixed Income','Trái phiếu','#35679d','#e8eff8'],['DE','Derivatives','Phái sinh','#9b4f67','#faebf0'],['AI','Alternative Investments','Đầu tư thay thế','#896d2d','#f7f0df'],['PM','Portfolio Management','Quản lý danh mục','#176e8c','#e0f4f9'],['ET','Ethical and Professional Standards','Đạo đức nghề nghiệp','#6f5d9f','#efeafa']];
const subs=subjectNames.map((v,i)=>({code:String(i+1).padStart(2,'0'),short:v[0],name:v[1],vi:v[2],tone:v[3],tint:v[4],modules:I.filter(m=>m.subject_code===String(i+1).padStart(2,'0'))}));const sm=Object.fromEntries(subs.map(x=>[x.code,x]));const subjectOf=id=>id.slice(6,8);const codeOf=l=>l.module.subject_code;const answerKey=(id,i)=>prefix+id+':'+i;function ans(id,i){let x=parse(read(answerKey(id,i)),null);return Number.isInteger(x)&&x>=0&&x<=2?x:null}function getCount(l){let n=0;for(let i=0;i<l.n;i++)if(ans(l.id,i)!==null)n++;return n}function status(l){return S.read[l.id]?'Đã học':getCount(l)?'Đang học':'Chưa học'}function counts(ls){let done=0,n=0,total=0;for(const l of ls){if(S.read[l.id])done++;n+=getCount(l);total+=l.n}return{done,n,total}}function knownWrong(){return Object.entries(S.marks).filter(([k,v])=>v&&v.wrong===true&&meta[k.split(':')[0]])}function dueCards(){return Object.entries(S.cards).filter(([k,v])=>v&&v.due<=Date.now()&&meta[k.split(':')[0]])}
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H10v7H4a1 1 0 0 1-1-1z',book:'M4 5h7a4 4 0 0 1 4 4v12a4 4 0 0 0-4-4H4z M15 9a4 4 0 0 1 4-4h1v12h-1a4 4 0 0 0-4 4',quiz:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',review:'M3 12a9 9 0 1 0 3-6.7L3 8m0-5v5h5M12 7v5l4 2',lab:'M9 3h6m-5 0v7L4 20h16l-6-10V3M7 15h10',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM15 15l5 5',moon:'M20 15a8 8 0 0 1-11-11A9 9 0 1 0 20 15z',menu:'M3 6h18M3 12h18M3 18h18',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM12 7v5l4 2',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z'};const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.book}"/></svg>`;
