function route(){let h=location.hash.slice(1);if(!h){let p=new URLSearchParams(location.search);if(p.get('module')){let m=I.find(x=>x.id===p.get('module'));if(m){let l=m.los.find(x=>x.id.endsWith(p.get('los')||'__'))||m.los[0];return ['lesson',l.id]}}return['home']}let [p,...r]=h.split('/');return[p,...r.map(x=>{try{return decodeURIComponent(x)}catch{return x}})]}function link(p,...r){return '#'+[p,...r.map(encodeURIComponent)].join('/')}function go(p,...r){let h=link(p,...r);if(location.hash===h)render();else location.hash=h}function toast(msg){$('toast').textContent=msg;$('toast').className='show';clearTimeout(toast.t);toast.t=setTimeout(()=>$('toast').className='',3500)}function toggleTheme(){S.dark=!S.dark;save();document.documentElement.classList.toggle('dark',S.dark);toast(S.dark?'Đã bật giao diện tối':'Đã bật giao diện sáng')}
const btn=(txt,act,cls='')=>`<button type="button" class="btn ${cls}" data-act="${esc(act)}">${txt}</button>`;const bar=(a,b)=>`<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct(a,b)}" aria-label="Tiến độ"><span style="width:${pct(a,b)}%"></span></div>`;const badge=(txt,cls='')=>`<span class="pill ${cls}">${esc(txt)}</span>`;const si=s=>`<div class="subject-icon" style="--tone:${s.tone};--tint:${s.tint}">${s.short}</div>`;const hrefLesson=(l,tab='learn')=>link('lesson',l.id,tab);
function shell(page){let active=['course','lesson','search'].includes(page)?'book':page;document.documentElement.classList.toggle('dark',S.dark);$('sidebar').innerHTML=`<a class="brand" href="#home"><span class="brand-mark">S</span><span><strong>Study Hub</strong><small>CFA Level I · 2026</small></span></a><button class="side-close" type="button" data-act="menu" aria-label="Ẩn thanh điều hướng">‹ Ẩn menu</button><div class="nav-caption">Học tập</div>${NAV.map(([k,t],i)=>`${i===5?'<div class="nav-caption">Công cụ</div>':''}<a class="nav-link ${active===k?'active':''}" href="#${k}">${icon(k)}${t}</a>`).join('')}<div class="side-bottom">Học theo tốc độ của bạn<br><a href="legacy.html">Kho học liệu gốc & lịch sử ↗</a></div>`;$('topbar').innerHTML=`<button class="icon-btn mobile-menu" data-act="menu" aria-controls="sidebar" aria-expanded="true" aria-label="Ẩn/hiện thanh điều hướng">${icon('menu')}</button><div class="top-title">${pages[page]||'Study Hub'}</div><form id="search-form" class="top-search" role="search">${icon('search')}<input name="q" aria-label="Tìm bài học" placeholder="Tìm bài học…" autocomplete="off"></form><button class="icon-btn" data-act="theme" aria-label="Đổi giao diện sáng tối">${icon('moon')}</button><div class="avatar" title="Hồ sơ học trên thiết bị">ME</div>`;let b=$('mobile-bottom');if(!b){b=document.createElement('nav');b.id='mobile-bottom';b.className='mobile-bottom';b.setAttribute('aria-label','Điều hướng nhanh');document.querySelector('.workspace').append(b)}b.innerHTML=NAV.slice(0,4).map(([k,t],i)=>`<button data-act="nav:${k}" class="${active===k?'active':''}">${icon(k)}${['Trang chủ','Môn học','Luyện tập','Ôn tập'][i]}</button>`).join('');if(!$('overlay')){let d=document.createElement('div');d.id='overlay';d.className='nav-overlay';d.dataset.act='menu';document.body.append(d)}document.body.classList.remove('nav-open');syncSidebar()}
function head(title,sub=''){return `<div class="lesson-head"><div class="eyebrow">CFA LEVEL I · 2026</div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>`}
function subjectCards(){return `<div class="subject-grid">${subs.map(s=>{const ls=s.modules.flatMap(m=>m.los),c=counts(ls);return `<a class="card subject-card" href="${link('course',s.code)}"><div class="row between">${si(s)}${badge(`${s.modules.length} modules`)}</div><div><div class="subject-title">${esc(s.name)}</div><div class="small">${esc(s.vi)}</div></div>${bar(c.done,ls.length)}<div class="row between small"><span>${c.done}/${ls.length} LOS đã học</span><span>${fmt(c.total)} MCQ</span></div></a>`}).join('')}</div>`}
function home(){let c=counts(all),last=meta[S.last]||all.find(l=>!S.read[l.id])||all[0],s=sm[codeOf(last)],w=knownWrong().length,d=dueCards().length;root.innerHTML=`<div class="hero"><div><div class="eyebrow">KHÔNG GIAN TỰ HỌC</div><h1>Học CFA theo cách của bạn.</h1><p>Mỗi lần một khái niệm. Hiểu bản chất, luyện câu hỏi tiếng Anh và ôn lại những phần chưa vững.</p><a class="btn" href="${hrefLesson(last)}">${S.last?'Học tiếp':'Bắt đầu học'} ${icon('arrow')}</a></div><svg class="hero-art" viewBox="0 0 210 180" aria-hidden="true"><rect x="15" y="20" width="180" height="138" rx="15" fill="#ffffff" opacity=".10"/><path d="M38 130h132M38 130V45" stroke="#b9daf7" stroke-width="1.4" opacity=".7"/><path d="m40 120 31-32 25 13 27-45 23 14 25-32" stroke="#85e7cf" stroke-width="4" stroke-linejoin="round" stroke-linecap="round" fill="none"/><g fill="#85e7cf"><circle cx="71" cy="88" r="5"/><circle cx="123" cy="56" r="5"/><circle cx="171" cy="38" r="5"/></g><rect x="83" y="117" width="82" height="40" rx="8" fill="#fff" opacity=".93"/><path d="m96 136 7 7 14-16" fill="none" stroke="#087e78" stroke-width="3"/><text x="123" y="141" fill="#245bc2" font-size="13" font-weight="700">CFA</text></svg></div><div class="stats">${[['Bài đã học',`${c.done}/365`,'Tự đánh dấu hoàn thành','book'],['Câu đã trả lời',fmt(c.n),`trên ${fmt(c.total)} câu chi tiết`,'quiz'],['Câu cần xem lại',fmt(w),'Câu sai ghi nhận trong trình học','review'],['Thẻ đến hạn',fmt(d),'Flashcard đã lên lịch','clock']].map(([a,b,t,k])=>`<div class="card stat"><div class="stat-label">${icon(k)}${a}</div><div class="stat-val">${b}</div><small>${t}</small></div>`).join('')}</div><div class="dashboard-grid"><div class="card"><div class="eyebrow">TIẾP TỤC LỘ TRÌNH</div><div class="focus-card" style="margin-top:12px">${si(s)}<div><h3>${esc(last.title)}</h3><p>${esc(s.name)} · LM ${last.module.number}.${last.letter}</p><a class="text-link" href="${hrefLesson(last)}">Mở bài học →</a></div></div></div><div class="card"><div class="eyebrow">LUYỆN TẬP HÔM NAY</div><h3 style="margin:10px 0 6px">${w?`Ôn lại ${fmt(w)} câu sai`:d?`Ôn ${fmt(d)} thẻ đến hạn`:'Một phiên 10 câu'}</h3><p class="small">${w?'Ưu tiên củng cố các câu bạn vừa làm sai.':d?'Ôn thẻ theo lịch đã đặt để duy trì ghi nhớ.':'Chọn môn và luyện câu chưa làm; nhận giải thích sau mỗi câu.'}</p><a class="btn primary" style="margin-top:12px" href="${w||d?'#review':'#quiz'}">${w||d?'Mở ôn tập':'Tạo phiên luyện'}</a></div></div><div class="section-head"><h2>10 môn học</h2><a href="#book" class="small">Xem thư viện →</a></div>${subjectCards()}<div class="section-head"><h2>Học bằng trực quan</h2><a href="#lab" class="small">Tất cả mô phỏng →</a></div><div class="card row between"><div><h3>Thay đổi số liệu, quan sát kết quả</h3><p class="small">TVM, bond price–yield, option payoff, rủi ro danh mục và các mô phỏng tài chính.</p></div><a class="btn" href="#lab">Khám phá ${icon('arrow')}</a></div>`}
