function losRow(l){let mm=meta[l.id]||l,n=getCount(mm);return `<a class="los-row" href="${hrefLesson(mm)}"><span class="circle ${S.read[l.id]?'done':''}">${S.read[l.id]?'✓':esc(l.letter)}</span><span class="title">${esc(l.title)}</span><span class="small">${n}/${l.n} câu</span><span aria-hidden="true">›</span></a>`}
