const files={'01':['deep-quant.js','CFA_DEEP_QUANT'],'02':['deep-econ.js','CFA_DEEP_ECON'],'03':['deep-ci.js','CFA_DEEP_CI'],'04':['deep-fsa.js','CFA_DEEP_FSA'],'05':['deep-equity.js','CFA_DEEP_EQUITY'],'06':['deep-fi.js','CFA_DEEP_FI'],'07':['deep-der.js','CFA_DEEP_DER'],'08':['deep-alt.js','CFA_DEEP_ALT'],'09':['deep-pm.js','CFA_DEEP_PM'],'10':['deep-eth.js','CFA_DEEP_ETH']};let scripts={},cache={};function script(file){if(!scripts[file])scripts[file]=new Promise((resolve,reject)=>{let x=document.createElement('script');x.src=file;x.onload=resolve;x.onerror=()=>{delete scripts[file];x.remove();reject(new Error('Không tải được '+file))};document.head.append(x)});return scripts[file]}async function load(code){if(cache[code])return cache[code];let [f,k]=files[code];await script(f);let a=window[k]||[];if(code==='01'){await script('quant-bridge.js');a=[...window.CFA_QUANT_BRIDGE,...a]}cache[code]=a;return a}async function loadLos(id){let a=await load(codeOf(meta[id]));let m=a.find(m=>m.module_id===meta[id].module.id);return{m,l:m.los.find(l=>l.id===id)}}
